import zipfile
import xml.etree.ElementTree as ET

NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
ns = {'m': NS}

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

expenses = {}
for row in root.findall('m:sheetData/m:row', ns):
    r = int(row.get('r'))
    if r < 11 or r > 22:
        continue
    cells = {c.get('r'): c for c in row.findall('m:c', ns)}
    cat = cells.get(f'A{r}').find('m:is', ns)
    cat = ''.join(t.text or '' for t in cat.iter('{%s}t' % NS))
    val = float(cells[f'C{r}'].find('m:v', ns).text)
    expenses[cat] = expenses.get(cat, 0.0) + val

total = sum(expenses.values())
for cat, v in expenses.items():
    print(f'{cat}: ${v:,.2f}')
print(f'TOTAL EXPENSES: ${total:,.2f}')

